package cli

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"github.com/spf13/cobra"

	"github.com/plumbkit/plumb/internal/fsync"
)

// omp's half of `plumb hooks`. omp has no hook config to merge into: it loads
// lifecycle handlers as TypeScript extension modules from <agent dir>/extensions,
// so plumb owns one generated file there, plumb.ts. The file is a thin bridge —
// each handler pipes one JSON document to the hidden `plumb hooks run-omp` verb
// and applies the answer — so every decision stays in Go, where the Claude Code
// and Codex packs keep theirs.
//
// What the pack does, in plumb's own event names (the status table's rows):
//
//   - SessionStart: on a session's first prompt, and again after a compaction,
//     state the omp session id that session_start records (before_agent_start).
//   - Stop: before a main-session turn ends, report unread peer mail
//     (session_stop → decision "block"). Like Codex, this narrows the
//     end-of-turn race; it cannot wake a session that is already idle.
//   - UserPromptSubmit / SubagentStart: the advisory context hints.
//
// Deliberately absent: the Claude Code identity stamp. omp re-validates a
// revised tool input and, for a call made through an xd:// device, answers the
// revision with a fresh approval prompt — stamping every plumb call would put a
// prompt in front of each one.

// ompHookOwnerMarker opens every file plumb generates. A file at the hooks path
// without it is the user's, and plumb refuses to change or delete it.
const ompHookOwnerMarker = "// Generated by `plumb hooks install omp`."

// ompHookEventMarker prefixes the line that records each installed event, so
// status and a partial uninstall read the file's contents rather than guess.
const ompHookEventMarker = "// plumb:hook "

// ompHookEvents are the events the pack can carry, in file order.
var ompHookEvents = []string{"SessionStart", "Stop", "UserPromptSubmit", "SubagentStart"}

var ompHooksTarget = hooksTarget{
	use:            "omp",
	name:           "omp",
	setup:          ompTarget,
	pathFn:         ompHooksPath,
	entries:        ompHookEntries,
	contextEntries: ompContextHookEntries,
	source:         ompExtensionSource,
	notes: []string{
		"omp — the extension loads in new sessions; restart a running omp to pick it up.",
		"omp — the Stop hook checks only as a main-session turn ends; it cannot wake an already-idle session.",
	},
}

// ompHooksPath returns the extension module plumb owns: <agent dir>/extensions/plumb.ts.
func ompHooksPath() (string, error) {
	dir, err := ompAgentDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(dir, "extensions", "plumb.ts"), nil
}

func ompHookEntries(string) []hookEntry {
	return []hookEntry{
		{event: "SessionStart", label: "session linkage"},
		{event: "Stop", label: "mailbox check"},
	}
}

func ompContextHookEntries(string) []hookEntry {
	return []hookEntry{
		{event: "UserPromptSubmit", label: "context hint"},
		{event: "SubagentStart", label: "subagent context hint"},
	}
}

// entryEvents lists the events a set of entries installs.
func entryEvents(entries []hookEntry) []string {
	out := make([]string, 0, len(entries))
	for _, e := range entries {
		out = append(out, e.event)
	}
	return out
}

// readHookSource reads a plumb-owned hook file. An absent file is ("", false);
// a present one without plumb's marker is an error, because it is the user's.
func readHookSource(path string) (content string, exists bool, err error) {
	data, err := os.ReadFile(path) //nolint:gosec // G304: path comes from the client registry, not from input
	if os.IsNotExist(err) {
		return "", false, nil
	}
	if err != nil {
		return "", false, fmt.Errorf("reading %s: %w", path, err)
	}
	content = string(data)
	if !strings.HasPrefix(content, ompHookOwnerMarker) {
		return "", true, fmt.Errorf("%s exists and was not written by plumb — refusing to change it", path)
	}
	return content, true, nil
}

// sourceEvents lists the events a generated file records, in file order.
func sourceEvents(content string) []string {
	var out []string
	for _, line := range strings.Split(content, "\n") {
		if ev, ok := strings.CutPrefix(line, ompHookEventMarker); ok {
			out = append(out, strings.TrimSpace(ev))
		}
	}
	return out
}

// sourceHookStates classifies entries against a generated file: missing when
// the file does not record the event, installed when the whole file is what
// this binary would write for the events it records, stale otherwise.
func sourceHookStates(t hooksTarget, path string, entries []hookEntry, plumbBin string) ([]hookState, error) {
	content, exists, err := readHookSource(path)
	if err != nil {
		return nil, err
	}
	have := sourceEvents(content)
	current := exists && content == t.source(plumbBin, have)
	out := make([]hookState, 0, len(entries))
	for _, e := range entries {
		switch {
		case !slices.Contains(have, e.event):
			out = append(out, hookState{entry: e, state: hookStateMissing})
		case current:
			out = append(out, hookState{entry: e, state: hookStateInstalled})
		default:
			out = append(out, hookState{entry: e, state: hookStateStale, detail: "file differs from this binary's — install refreshes it"})
		}
	}
	return out, nil
}

// installHookSource writes the file for entries, returning whether it changed.
// An edited copy of plumb's own file is backed up before it is replaced.
func installHookSource(t hooksTarget, path string, entries []hookEntry, plumbBin string) (bool, error) {
	content, exists, err := readHookSource(path)
	if err != nil {
		return false, err
	}
	want := t.source(plumbBin, entryEvents(entries))
	if exists && content == want {
		return false, nil
	}
	return true, writeHookSource(t, path, want, content, exists)
}

// removeHookSource takes events (nil for every one) out of the file and reports
// how many went. The file is deleted once nothing is left in it.
func removeHookSource(t hooksTarget, path string, events []string, plumbBin string) (int, error) {
	content, exists, err := readHookSource(path)
	if err != nil || !exists {
		return 0, err
	}
	have := sourceEvents(content)
	var keep []string
	for _, ev := range have {
		if events != nil && !slices.Contains(events, ev) {
			keep = append(keep, ev)
		}
	}
	removed := len(have) - len(keep)
	if removed == 0 {
		return 0, nil
	}
	if len(keep) == 0 {
		if err := backupEditedHookSource(t, path, content); err != nil {
			return 0, err
		}
		if err := os.Remove(path); err != nil {
			return 0, fmt.Errorf("removing %s: %w", path, err)
		}
		return removed, nil
	}
	return removed, writeHookSource(t, path, t.source(plumbBin, keep), content, true)
}

// ompBinaryLinePrefix opens the template line that names the plumb binary.
const ompBinaryLinePrefix = "const PLUMB: string = "

// backupEditedHookSource backs the file up only when someone edited it: when
// it is not exactly what plumb renders for the binary and events it records.
// plumb's own untouched output is regenerated at will, so copying it would only
// leave .bak files in omp's extensions directory.
func backupEditedHookSource(t hooksTarget, path, content string) error {
	bin := ""
	for _, line := range strings.Split(content, "\n") {
		if lit, ok := strings.CutPrefix(line, ompBinaryLinePrefix); ok {
			_ = json.Unmarshal([]byte(strings.TrimSuffix(lit, ";")), &bin)
			break
		}
	}
	if content == t.source(bin, sourceEvents(content)) {
		return nil
	}
	if err := backupFile(path); err != nil {
		return fmt.Errorf("backing up %s: %w", path, err)
	}
	return nil
}

func writeHookSource(t hooksTarget, path, content, previous string, exists bool) error {
	if exists {
		if err := backupEditedHookSource(t, path, previous); err != nil {
			return err
		}
	} else if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("creating %s: %w", filepath.Dir(path), err)
	}
	// The staging file is dot-prefixed: omp skips hidden entries when it scans
	// extensions/, so a crash mid-write never leaves a half module it would load.
	if err := fsync.AtomicWrite(path, []byte(content), setupWriteOptions(".plumb_omp_ext_*.ts")); err != nil {
		return fmt.Errorf("writing %s: %w", path, err)
	}
	return nil
}

// ompExtensionSource renders the extension module for events. The file records
// each event on a marker line and switches each feature on by constant, so one
// template serves every subset `--no-context` and `uninstall --only context`
// can leave.
func ompExtensionSource(plumbBin string, events []string) string {
	bin, _ := json.Marshal(plumbBin) // a JSON string is a valid TypeScript string literal
	var b strings.Builder
	b.WriteString(ompHookOwnerMarker + "\n")
	b.WriteString("// plumb rewrites this file on install and deletes it on uninstall, saving an\n")
	b.WriteString("// edited copy as a .bak first. Every handler fails open: a missing plumb, a\n")
	b.WriteString("// stopped daemon or a slow answer leaves the turn exactly as omp would run it.\n")
	for _, ev := range ompHookEvents {
		if slices.Contains(events, ev) {
			b.WriteString(ompHookEventMarker + ev + "\n")
		}
	}
	fmt.Fprintf(&b, ompExtensionTemplate, bin,
		slices.Contains(events, "SessionStart"), slices.Contains(events, "Stop"),
		slices.Contains(events, "UserPromptSubmit"), slices.Contains(events, "SubagentStart"))
	return b.String()
}

// ompExtensionTemplate is the module body. It needs nothing beyond omp's
// extension API and the Bun runtime omp itself runs on; Bun.spawn rather than
// pi.exec because the payload goes over stdin, keeping prompts out of argv.
const ompExtensionTemplate = `
` + ompBinaryLinePrefix + `%s;
const LINK = %t; // state the session id plumb's session_start records
const MAIL = %t; // report unread peer mail before a main-session turn ends
const HINTS = %t; // context hints on prompts
const SUB_HINTS = %t; // the context-hint rule when a subagent starts

// Session ids already told their linkage; cleared on compaction so the next
// prompt states it again.
const linked = new Set<string>();

type Reply = { context?: string; decision?: string; reason?: string };

async function ask(payload: Record<string, unknown>): Promise<Reply | undefined> {
	try {
		const proc = Bun.spawn([PLUMB, "hooks", "run-omp"], {
			stdin: new Blob([JSON.stringify(payload)]),
			stdout: "pipe",
			stderr: "ignore",
			signal: AbortSignal.timeout(5000),
		});
		const out = await new Response(proc.stdout).text();
		if ((await proc.exited) !== 0 || out.trim() === "") return undefined;
		return JSON.parse(out) as Reply;
	} catch {
		return undefined;
	}
}

export default function plumb(pi: any): void {
	if (LINK) {
		pi.on("session_compact", (_event: unknown, ctx: any) => {
			try {
				linked.delete(ctx.sessionManager.getSessionId());
			} catch {}
		});
	}
	if (LINK || HINTS || SUB_HINTS) {
		pi.on("before_agent_start", async (event: any, ctx: any) => {
			if (event.reason === "revive") return;
			const id: string = ctx.sessionManager.getSessionId();
			const sub = ctx.agent?.kind === "sub";
			const link = LINK && !sub && !linked.has(id);
			const hint = sub ? SUB_HINTS : HINTS;
			if (!link && !hint) return;
			const reply = await ask({
				event: sub ? "SubagentStart" : "UserPromptSubmit",
				session_id: id,
				cwd: ctx.cwd,
				prompt: sub ? "" : event.prompt,
				link,
				hint,
			});
			if (!reply?.context) return;
			if (link) linked.add(id);
			return { message: { customType: "plumb.context", content: reply.context, display: false } };
		});
	}
	if (MAIL) {
		pi.on("session_stop", async (event: any, ctx: any) => {
			const reply = await ask({
				event: "Stop",
				session_id: event.session_id ?? ctx.sessionManager.getSessionId(),
				cwd: ctx.cwd,
				stop_hook_active: event.stop_hook_active === true,
			});
			if (reply?.decision === "block") return { decision: "block", reason: reply.reason };
		});
	}
}
`

var hooksRunOmpCmd = &cobra.Command{
	Use:         "run-omp",
	Short:       "Run an omp lifecycle hook",
	Hidden:      true,
	Annotations: map[string]string{annoSkipLogo: "true"}, // stdout belongs to the extension
	Args:        cobra.NoArgs,
	RunE: func(_ *cobra.Command, _ []string) error {
		return runOmpHookIO(os.Stdin, os.Stdout, hookStopMailReport, askContextHint)
	},
}

// ompHookInput is what the extension sends: plumb's event name, the omp
// session id, and the switches the extension already decided.
type ompHookInput struct {
	Event          string `json:"event"`
	SessionID      string `json:"session_id"`
	CWD            string `json:"cwd"`
	Prompt         string `json:"prompt"`
	Link           bool   `json:"link"`
	Hint           bool   `json:"hint"`
	StopHookActive bool   `json:"stop_hook_active"`
}

// ompHookOutput is what the extension applies: context to inject, or a Stop
// decision.
type ompHookOutput struct {
	Context  string `json:"context,omitempty"`
	Decision string `json:"decision,omitempty"`
	Reason   string `json:"reason,omitempty"`
}

// ompHookStdinCap bounds the payload; it carries the user's prompt, which a
// pasted log can make large.
const ompHookStdinCap = 4 << 20

func runOmpHookIO(in io.Reader, out io.Writer, probe func(string, string) (mailReport, bool), ask func(contextHintRequest) string) error {
	var input ompHookInput
	if err := json.NewDecoder(io.LimitReader(in, ompHookStdinCap)).Decode(&input); err != nil {
		return nil // a hook failure must never strand an omp turn
	}
	output := ompHookResult(input, probe, ask)
	if output == nil {
		return nil
	}
	return json.NewEncoder(out).Encode(output)
}

// ompHookResult is the pure core, with the daemon probes injected.
func ompHookResult(input ompHookInput, probe func(string, string) (mailReport, bool), ask func(contextHintRequest) string) *ompHookOutput {
	id := strings.TrimSpace(input.SessionID)
	if id == "" {
		return nil
	}
	var parts []string
	switch input.Event {
	case "UserPromptSubmit":
		if input.Link {
			parts = append(parts, sessionLinkageSentence(id, "omp conversation"))
		}
		if input.Hint {
			parts = append(parts, ompContextHintText(input, id, ask))
		}
	case "SubagentStart":
		if input.Hint {
			parts = append(parts, ompContextHintText(input, id, ask))
		}
	case "Stop":
		if input.StopHookActive || probe == nil {
			return nil
		}
		report, ok := probe(id, input.CWD)
		if !ok || report.Count == 0 {
			return nil
		}
		return &ompHookOutput{Decision: "block", Reason: peerMailStopReason(report.Count)}
	}
	parts = slices.DeleteFunc(parts, func(s string) bool { return s == "" })
	if len(parts) == 0 {
		return nil
	}
	return &ompHookOutput{Context: strings.Join(parts, "\n\n")}
}

// ompContextHintText asks for an omp event's hint. omp has no turn id here, so
// each prompt opens a new allowance window, as on Claude Code. Outside a plumb
// workspace it asks nothing.
func ompContextHintText(input ompHookInput, id string, ask func(contextHintRequest) string) string {
	root, inside := plumbWorkspaceRoot(input.CWD)
	if !inside || ask == nil {
		return ""
	}
	req := contextHintRequest{
		Host: "omp", Event: input.Event, SessionID: id, Workspace: root,
		NamespaceToken: hookNamespaceToken(),
	}
	if input.Event == "UserPromptSubmit" {
		req.Selectors = promptSelectors(input.Prompt)
	}
	return strings.TrimRight(ask(req), "\n")
}
